SELECT
    ,
    ,




    t.is_deleted = 0


        AND (t.training_no LIKE CONCAT('%', #{q.keyword}, '%')
        OR t.training_name LIKE CONCAT('%', #{q.keyword}, '%')
        OR t.address LIKE CONCAT('%', #{q.keyword}, '%'))


        AND t.training_type = #{q.trainingType}


        AND t.train_mode = #{q.trainMode}


        AND t.status = #{q.status}




        AND t.start_time >= #{q.startFrom}


        AND t.start_time <= #{q.startTo}



ORDER BY t.id DESC
